const businessHours = {
  2: { open: '10:30', close: '18:30' }, // Tuesday
  3: { open: '10:30', close: '18:30' }, // Wednesday
  4: { open: '10:30', close: '18:30' }, // Thursday
  5: { open: '10:30', close: '18:30' }, // Friday
  6: { open: '10:30', close: '16:00' }, // Saturday
};
const DURATION_MIN = 60;
const STEP_MIN = 30;
const DAYS_AHEAD = 14;

const busyEvents = $input.all()
  .map(item => item.json)
  .filter(e => e && e.start && e.start.dateTime && e.end && e.end.dateTime);

const now = $now.setZone('Europe/Berlin');
const days = [];

for (let i = 0; i < DAYS_AHEAD; i++) {
  const day = now.plus({ days: i }).startOf('day');
  const weekday = day.weekday; // 1=Mon..7=Sun
  const hours = businessHours[weekday];
  const dateStr = day.toFormat('yyyy-LL-dd');
  const weekdayName = day.toFormat('cccc');

  if (!hours) {
    days.push({ date: dateStr, weekday: weekdayName, closed: true, slots: [] });
    continue;
  }

  const [openH, openM] = hours.open.split(':').map(Number);
  const [closeH, closeM] = hours.close.split(':').map(Number);
  const openDt = day.set({ hour: openH, minute: openM });
  const closeDt = day.set({ hour: closeH, minute: closeM });

  const slots = [];
  let slotStart = openDt;
  while (slotStart.plus({ minutes: DURATION_MIN }) <= closeDt) {
    if (slotStart > now) {
      const slotEnd = slotStart.plus({ minutes: DURATION_MIN });
      const overlaps = busyEvents.some(e => {
        const busyStart = DateTime.fromISO(e.start.dateTime);
        const busyEnd = DateTime.fromISO(e.end.dateTime);
        return slotStart < busyEnd && slotEnd > busyStart;
      });
      if (!overlaps) {
        slots.push({ time: slotStart.toFormat('HH:mm'), iso: slotStart.toISO() });
      }
    }
    slotStart = slotStart.plus({ minutes: STEP_MIN });
  }

  days.push({ date: dateStr, weekday: weekdayName, closed: false, full: slots.length === 0, slots });
}

return [{ json: { generatedAt: now.toISO(), days } }];
